import unittest
from solution import frequency

class T(unittest.TestCase):
    def test_basic(self):
        self.assertEqual(frequency("a b a"), {"a": 2, "b": 1})
    def test_case(self):
        self.assertEqual(frequency("Hi hi HI"), {"hi": 3})
    def test_empty(self):
        self.assertEqual(frequency(""), {})
    def test_punct(self):
        self.assertEqual(frequency("a, a,"), {"a,": 2})
